// ScheduleResolver.java — resolves local schedule rules to absolute UTC instants
package com.nbi.db;

import java.time.*;
import java.time.format.DateTimeFormatter;

public class ScheduleResolver {

    // Given a business local time + named zone + date, return the UTC instant to fire.
    // Handles DST because ZonedDateTime uses the IANA tz database rules.
    public Instant utcFireInstant(LocalDate date, LocalTime localTime, ZoneId zone) {
        ZonedDateTime local = ZonedDateTime.of(date, localTime, zone); // local wall-clock
        return local.toInstant();                                       // → absolute UTC instant
    }

    // Convert a stored UTC instant to a display zone (conversion only at the edge).
    public String display(Instant utc, ZoneId zone) {
        return utc.atZone(zone).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm z"));
    }
}
