// Demo.java — UTC storage, edge conversion, and DST-aware scheduling
package com.nbi.db;

import java.time.*;

public class Demo {
    public static void main(String[] args) {
        ScheduleResolver resolver = new ScheduleResolver();
        ZoneId ist = ZoneId.of("Asia/Kolkata");       // no DST, fixed +05:30
        ZoneId ny  = ZoneId.of("America/New_York");    // observes DST

        // --- "Run EOD settlement at 9:00 PM IST" -> correct UTC fire instant ---
        LocalTime nine_pm = LocalTime.of(21, 0);
        Instant istFire = resolver.utcFireInstant(LocalDate.of(2026, 1, 15), nine_pm, ist);
        System.out.println("EOD 21:00 IST fires at UTC instant: " + istFire);
        System.out.println("  shown in IST: " + resolver.display(istFire, ist));
        System.out.println("  shown in UTC: " + resolver.display(istFire, ZoneId.of("UTC")));

        // --- DST trap: 9:00 PM New York maps to DIFFERENT UTC instants summer vs winter ---
        Instant nyWinter = resolver.utcFireInstant(LocalDate.of(2026, 1, 15), nine_pm, ny); // EST -05:00
        Instant nySummer = resolver.utcFireInstant(LocalDate.of(2026, 7, 15), nine_pm, ny); // EDT -04:00
        System.out.println("9:00 PM New York in winter (EST) -> UTC: " + resolver.display(nyWinter, ZoneId.of("UTC")));
        System.out.println("9:00 PM New York in summer (EDT) -> UTC: " + resolver.display(nySummer, ZoneId.of("UTC")));
        System.out.println("  Same local 21:00 NY, different UTC instants -> DST handled by tz database.");
    }
}
